import 'dart:io' show Platform;
import 'dart:math';

import 'package:dio/dio.dart';
import 'package:flutter/foundation.dart';

import 'models.dart';
import 'apple_kit.dart';
import 'lyrics.dart';
import 'source.dart';

/// Apple Music, read through the Apple Music REST API and played through the
/// platform's own MusicKit player.
///
/// Two tokens are involved and both come from the system: the *developer*
/// token identifies this app and is generated by MusicKit itself (the app does
/// not ship a key), and the *music user* token says which Apple Music
/// account's library to read. Neither is a password and neither expires in a
/// way the app has to think about: re-connecting asks for fresh ones.
class AppleMusicAdapter implements LibraryAdapter {
  /// [musicKit] is injectable so the connect flow can be exercised without
  /// the plugin; the app never passes one.
  AppleMusicAdapter({MusicKitClient? musicKit, String? apiRoot})
    : _musicKit = musicKit ?? MusicKitClient(),
      _apiRoot = apiRoot ?? kAppleMusicApiRoot;

  final MusicKitClient _musicKit;

  /// The API root stored on a new connection. Tests point it at a local
  /// server; the app always uses Apple's.
  final String _apiRoot;

  @override
  LibraryKind get kind => LibraryKind.appleMusic;

  /// There is nothing to type: the account is whatever the system is signed
  /// into, so the setup form's fields are ignored.
  @override
  Future<SourceConfig> connect({
    required String baseUrl,
    required String username,
    required String password,
  }) async {
    if (!AppleMusicSource.isSupported) throw _unsupported;

    final musicKit = _musicKit;
    final status = await musicKit.requestAuthorization();
    if (!status) throw _denied;

    final developerToken = await musicKit.developerToken();
    if (developerToken.isEmpty) throw _noDeveloperToken;
    final userToken = await musicKit.userToken(developerToken);
    if (userToken.isEmpty) throw _denied;

    final config = SourceConfig(
      id: newSourceId(LibraryKind.appleMusic),
      kind: LibraryKind.appleMusic,
      baseUrl: _apiRoot,
      displayName: 'Apple Music',
      auth: {'developerToken': developerToken, 'userToken': userToken},
    );
    // One signed-in read proves both tokens work before the source is stored.
    await AppleMusicSource(config).verify();
    return config;
  }

  @override
  LibrarySource sourceFor(SourceConfig config) => AppleMusicSource(config);

  /// Apple Music signs in through the system: there is no address or
  /// password to type.
  @override
  bool get needsCredentials => false;

  /// Only iOS and macOS 14+ can play what this adapter reads.
  @override
  bool get isAvailable => AppleMusicSource.isSupported;

  static const _unsupported = LibraryException(
    'Apple Music is not available on this device.',
    messageKey: 'libraryAppleMusicUnsupported',
  );
  static const _denied = LibraryException(
    'Apple Music access was refused. Allow it in System Settings, then try again.',
    messageKey: 'libraryAppleMusicDenied',
  );
  static const _noDeveloperToken = LibraryException(
    'Apple Music did not issue a developer token for this app.',
    messageKey: 'libraryAppleMusicNoToken',
  );
}

/// The API root every Apple Music read is relative to.
const kAppleMusicApiRoot = 'https://api.music.apple.com';

/// One signed-in Apple Music account.
///
/// It implements three capabilities rather than being special-cased by kind:
/// [PlatformPlayedSource] because the sound comes from MusicKit's own player,
/// [CuratedSource] because the account curates its own landing page, and the
/// plain [LibrarySource] reads. A future provider that is played by a platform
/// player adds itself to exactly the same interfaces.
class AppleMusicSource extends LibrarySource
    implements PlatformPlayedSource, CuratedSource, ExtendableSource {
  @override
  final SourceConfig config;
  final Dio _dio;

  AppleMusicSource(this.config)
    : _dio = Dio(
        BaseOptions(
          // The API root, kept as the stored address so nothing else has to
          // know that an Apple Music source has no user-typed host.
          baseUrl: config.baseUrl.isEmpty ? kAppleMusicApiRoot : config.baseUrl,
          connectTimeout: const Duration(seconds: 12),
          receiveTimeout: const Duration(seconds: 25),
          responseType: ResponseType.json,
          headers: {
            'Authorization': 'Bearer ${config.auth['developerToken'] ?? ''}',
            'Music-User-Token': config.auth['userToken'] ?? '',
            // Apple answers differently without it; the app has no
            // server-side proxy to localise reads.
            'Accept-Language': 'en',
          },
        ),
      );

  /// MusicKit's own player can only play on iOS 15+ and macOS 14+. Reads
  /// still work without it, but a library that cannot be heard is not a
  /// library the setup screen should offer.
  static bool get isSupported {
    if (kIsWeb) return false;
    if (Platform.isIOS) return true;
    if (!Platform.isMacOS) return false;
    final match = RegExp(r'Version (\d+)')
        .firstMatch(Platform.operatingSystemVersion);
    final major = match == null ? 0 : int.parse(match.group(1)!);
    return major >= 14;
  }

  /// The account is the device's, not an address: Settings shows the kind
  /// alone rather than an API endpoint nobody typed.
  @override
  String get addressLabel => '';

  static const _signedOut = LibraryException(
    'This Apple Music account is not signed in. Connect it again from Settings.',
    messageKey: 'librarySignedOut',
  );

  /// Confirms both tokens still work.
  Future<void> verify() => _get('/v1/me/library/artists', query: {'limit': 1});

  Future<Map<String, dynamic>> _get(
    String path, {
    Map<String, dynamic>? query,
  }) async {
    if (config.auth['developerToken'] == null ||
        config.auth['userToken'] == null) {
      throw _signedOut;
    }
    final Response<dynamic> response;
    try {
      response = await _dio.get<dynamic>(path, queryParameters: query);
    } on DioException catch (error) {
      final status = error.response?.statusCode;
      if (status == 401 || status == 403) {
        throw LibraryException(
          'Apple Music refused the request (HTTP $status).',
          code: status,
          messageKey: status == 403
              ? 'libraryAppleMusicSubscription'
              : 'libraryAppleMusicSignedOut',
        );
      }
      if (error.type == DioExceptionType.badResponse) {
        throw LibraryException(
          'Apple Music returned HTTP $status.',
          code: status,
          messageKey: 'libraryHttpError',
          messageArgs: [status?.toString() ?? 'error'],
        );
      }
      throw describeAppleError(error);
    }

    final data = response.data;
    if (data is! Map) throw _malformed;
    return Map<String, dynamic>.from(data);
  }

  /// Every list endpoint answers with `{data: [...], next?}`.
  Future<List<Map<String, dynamic>>> _data(
    String path, {
    Map<String, dynamic>? query,
  }) async {
    final body = await _get(path, query: query);
    return _resources(body);
  }

  static List<Map<String, dynamic>> _resources(Map<String, dynamic> body) {
    final data = body['data'];
    if (data is! List) return const [];
    return [
      for (final item in data)
        if (item is Map) Map<String, dynamic>.from(item),
    ];
  }

  @override
  Future<List<LibraryAlbum>> recentlyAdded({int limit = 50}) async {
    // `recently-added` mixes albums and playlists; only albums belong on the
    // "newest" shelf.
    final items = await _data(
      '/v1/me/library/recently-added',
      query: {'limit': limit},
    );
    return [
      for (final item in items)
        if (item['type'] == 'library-albums') _album(item),
    ];
  }

  @override
  Future<List<LibraryAlbum>> albums({int limit = 60, int offset = 0}) async {
    final items = await _data(
      '/v1/me/library/albums',
      query: {'limit': limit, 'offset': offset},
    );
    return [for (final item in items) _album(item)];
  }

  @override
  Future<LibraryAlbum?> album(String albumId) async {
    final items = await _data('/v1/me/library/albums/${_path(albumId)}');
    return items.isEmpty ? null : _album(items.first);
  }

  @override
  Future<List<LibrarySong>> albumSongs(String albumId) async {
    final items = await _data('/v1/me/library/albums/${_path(albumId)}/tracks');
    return [for (final item in items) _song(item, albumId: albumId)];
  }

  @override
  Future<List<LibraryArtist>> artists() async {
    final items = await _data('/v1/me/library/artists', query: {'limit': 100});
    return [
      for (final item in items)
        LibraryArtist(
          sourceId: id,
          id: '${item['id']}',
          name: _attributes(item)['name'] as String? ?? 'Unknown artist',
        ),
    ];
  }

  @override
  Future<List<LibraryAlbum>> artistAlbums(String artistId) async {
    final items = await _data(
      '/v1/me/library/artists/${_path(artistId)}/albums',
    );
    return [for (final item in items) _album(item)];
  }

  @override
  Future<List<LibraryPlaylist>> playlists() async {
    final items = await _data(
      '/v1/me/library/playlists',
      query: {'limit': 100},
    );
    return [
      for (final item in items)
        LibraryPlaylist(
          sourceId: id,
          id: '${item['id']}',
          name: _attributes(item)['name'] as String? ?? 'Untitled playlist',
          duration: Duration.zero,
        ),
    ];
  }

  @override
  Future<List<LibrarySong>> playlistSongs(String playlistId) async {
    final items = await _data(
      '/v1/me/library/playlists/${_path(playlistId)}/tracks',
    );
    return [for (final item in items) _song(item)];
  }

  @override
  Future<List<LibrarySong>> search(String query, {int limit = 40}) async {
    final term = query.trim();
    if (term.isEmpty) return const [];
    final body = await _get(
      '/v1/me/library/search',
      query: {'term': term, 'types': 'library-songs', 'limit': limit},
    );
    final results = body['results'];
    final songs = results is Map ? results['library-songs'] : null;
    if (songs is! Map) return const [];
    return [
      for (final item in _resources(Map<String, dynamic>.from(songs)))
        _song(item),
    ];
  }

  /// The account's own curation, as shelves for the landing page.
  ///
  /// Apple answers recommendations as *containers*: each one names the kinds
  /// its contents will be (`resourceTypes`) and holds them behind a separate
  /// `contents` href. Only containers whose contents are playable tracks or
  /// albums are worth a shelf; a station suggestion and a record-label mix
  /// look the same in the list and are told apart by that types field.
  @override
  Future<List<LandingShelf>> landingShelves() async {
    final containers = await _data(
      '/v1/me/recommendations',
      query: {'limit': 10},
    );
    final shelves = await Future.wait([
      for (final container in containers) _shelfFor(container),
    ]);
    return [
      for (final shelf in shelves)
        if (shelf != null && !shelf.isEmpty) shelf,
    ];
  }

  /// One recommendation container, or null when it holds nothing the app can
  /// play.
  ///
  /// A container listing `stations` gets the stations it suggests, which play
  /// the same way a song does here ([_station]); one listing albums or
  /// playlists reads them out of the catalog. Both are only attempted for the
  /// kinds [LandingShelf] can hold, so a "recently played" container mixing
  /// all three still yields something.
  Future<LandingShelf?> _shelfFor(Map<String, dynamic> container) async {
    final attributes = _attributes(container);
    final title = _displayTitle(attributes['title']);
    final types = attributes['resourceTypes'];
    if (title == null || types is! List) return null;

    final relationships = container['relationships'];
    final contents = relationships is Map ? relationships['contents'] : null;
    final href = contents is Map ? contents['href'] : null;
    if (href is! String) return null;

    try {
      final items = await _data(href, query: {'limit': 12});
      final songs = <LibrarySong>[];
      for (final item in items) {
        switch (item['type']) {
          case 'stations':
            songs.add(_station(item));
          case 'songs' || 'library-songs':
            songs.add(_song(item));
          case 'albums' || 'library-albums':
            // An album in a mix is not a track; its own page is the useful
            // thing, so the shelf stays to what plays in one tap.
            continue;
        }
      }
      if (songs.isEmpty) return null;
      return LandingShelf(title: title, sourceId: id, songs: songs);
    } on LibraryException {
      // One unreadable recommendation must not blank the rest of the page.
      return null;
    }
  }

  /// What the account has, for the landing page's header card.
  @override
  Future<LibraryDigest?> digest() async {
    final tracks = await _count('/v1/me/library/songs');
    return LibraryDigest(
      sourceId: id,
      // The API has no account-name endpoint an app token can reach; the kind
      // is the honest label, and the size is the point of the card.
      subtitle: displayName,
      libraryTracks: tracks,
    );
  }

  /// A collection's size. Apple pages a library and reports its total, so one
  /// row is enough. A collection without a total (recommendations never carry
  /// one) answers null rather than a wrong number.
  Future<int?> _count(String path, {Map<String, dynamic>? query}) async {
    try {
      final body = await _get(path, query: {...?query, 'limit': 1});
      final meta = body['meta'];
      return meta is Map ? (meta['total'] as num?)?.toInt() : null;
    } on LibraryException {
      return null;
    }
  }

  /// A station as the transport knows it: a song with no length that the
  /// platform player starts from [radioResource].
  LibrarySong _station(Map<String, dynamic> json) {
    final attributes = _attributes(json);
    final playParams = attributes['playParams'];
    return LibrarySong(
      sourceId: id,
      id: '${json['id']}',
      title: attributes['name'] as String? ?? 'Radio',
      artId: _artTemplate(attributes),
      duration: Duration.zero,
      isRadio: true,
      radioUrl: attributes['url'] as String?,
      radioPlayParams: playParams is Map
          ? Map<String, dynamic>.from(playParams)
          : null,
    );
  }

  /// The resource the system player resolves [song] from.
  ///
  /// A station is rebuilt from what [_station] kept rather than the raw JSON:
  /// the queue round-trips through the saved session, and a station has to
  /// survive being written and read back.
  @override
  Map<String, dynamic> platformResource(LibrarySong song) {
    if (!song.isRadio) {
      return {
        'id': song.id,
        'type': 'songs',
        'attributes': {
          'name': song.title,
          if (song.artist != null) 'artistName': song.artist,
          if (song.album != null) 'albumName': song.album,
          'durationInMillis': song.duration.inMilliseconds,
          'playParams': {'id': song.id, 'kind': 'song', 'isLibrary': true},
        },
      };
    }
    final url = song.radioUrl;
    final playParams = song.radioPlayParams;
    return {
      'id': song.id,
      'type': 'stations',
      'attributes': {
        'name': song.title,
        'isLive': false,
        'mediaKind': 'audio',
        'url': ?url,
        'playParams': ?playParams,
      },
    };
  }

  /// Searches the store, not just the account.
  ///
  /// `/v1/me/library/search` only answers with what is already added; the
  /// catalog endpoint is the other half, and it is what makes "find something
  /// new and keep it" possible.
  @override
  Future<CatalogSearch> searchCatalog(String query, {int limit = 25}) async {
    final term = query.trim();
    if (term.isEmpty) return const CatalogSearch();
    final storefront = await _storefront();
    final body = await _get(
      '/v1/catalog/$storefront/search',
      query: {'term': term, 'types': 'songs,albums,playlists', 'limit': limit},
    );
    final results = body['results'];
    if (results is! Map) return const CatalogSearch();

    List<Map<String, dynamic>> items(String kind) {
      final section = results[kind];
      if (section is! Map) return const [];
      return _resources(Map<String, dynamic>.from(section));
    }

    return CatalogSearch(
      songs: [for (final item in items('songs')) _song(item)],
      albums: [for (final item in items('albums')) _album(item)],
      playlists: [
        for (final item in items('playlists'))
          LibraryPlaylist(
            sourceId: id,
            id: '${item['id']}',
            name: _attributes(item)['name'] as String? ?? 'Untitled playlist',
            duration: Duration.zero,
            artId: _artTemplate(_attributes(item)),
          ),
      ],
    );
  }

  /// Adds catalog [ids] of one [kind] to the account's library.
  ///
  /// The store takes `ids[<kind>]` as a bracketed form parameter and answers
  /// 202 for an accepted add; it validates the parameter name strictly
  /// (anything else is "ids parameter is required"), so the brackets are part
  /// of the request rather than a serialiser's choice.
  @override
  Future<int> addToLibrary(CatalogKind kind, List<String> ids) async {
    if (ids.isEmpty) return 0;
    final items = kind.name;
    try {
      await _dio.post<void>(
        '/v1/me/library',
        queryParameters: {'ids[$items]': ids.join(',')},
      );
      return ids.length;
    } on DioException catch (error) {
      final status = error.response?.statusCode;
      if (status == 401 || status == 403) {
        throw LibraryException(
          'Apple Music refused to add to the library (HTTP $status).',
          code: status,
          messageKey: 'libraryAppleMusicSubscription',
        );
      }
      throw describeAppleError(error);
    }
  }

  /// Whether the account favourited [song].
  ///
  /// Ratings are keyed by *catalog* id: the library id is refused with
  /// "Ratings not allowed for resource type 'songs'", so a track that only
  /// exists in the account's library cannot be rated at all, and the answer
  /// is false rather than an error the UI would have to explain.
  @override
  Future<bool> isFavourite(LibrarySong song) async {
    final catalogId = await _catalogIdOf(song);
    if (catalogId == null) return false;
    try {
      final body = await _get('/v1/me/ratings/songs/${_path(catalogId)}');
      final items = _resources(body);
      if (items.isEmpty) return false;
      final attributes = _attributes(items.first);
      // 1 is a like; -1 is a dislike, which is not a favourite.
      return (attributes['value'] as num?)?.toInt() == 1;
    } on LibraryException catch (error) {
      // 404 is the API's way of saying "not rated", which is an answer.
      if (error.code == 404) return false;
      rethrow;
    }
  }

  @override
  Future<void> setFavourite(LibrarySong song, {required bool value}) async {
    final catalogId = await _catalogIdOf(song);
    if (catalogId == null) {
      throw const LibraryException(
        'Only a track in the store can be favourited.',
        messageKey: 'libraryAppleMusicNoCatalogId',
      );
    }
    final path = '/v1/me/ratings/songs/${_path(catalogId)}';
    if (!value) {
      // Clearing is its own verb: PUT with value 0 leaves the rating row.
      await _write('delete', path);
      return;
    }
    await _write(
      'put',
      path,
      body: {
        'type': 'ratings',
        'attributes': {'value': 1},
      },
    );
  }

  /// The account's playlists it can still add to.
  ///
  /// `canEdit` is the service's own answer and the only reliable one: the
  /// favourites mix ("喜爱歌曲", "Favourite Songs") is listed among the
  /// account's playlists but answers 204 to an add and silently drops it,
  /// because it is a view of every like rather than a list you edit.
  @override
  Future<List<LibraryPlaylist>> editablePlaylists() async {
    final items = await _data(
      '/v1/me/library/playlists',
      query: {'limit': 100},
    );
    return [
      for (final item in items)
        if (_attributes(item)['canEdit'] == true)
          LibraryPlaylist(
            sourceId: id,
            id: '${item['id']}',
            name: _attributes(item)['name'] as String? ?? 'Untitled playlist',
            duration: Duration.zero,
            songCount: (_attributes(item)['trackCount'] as num?)?.toInt(),
            artId: _artTemplate(_attributes(item)),
          ),
    ];
  }

  @override
  Future<void> addToPlaylist(LibraryPlaylist playlist, LibrarySong song) async {
    final partnerId = await _catalogIdOf(song);
    if (partnerId == null) {
      throw const LibraryException(
        'Only a track in the store can be added to a playlist.',
        messageKey: 'libraryAppleMusicNoCatalogId',
      );
    }
    await _write(
      'post',
      '/v1/me/library/playlists/${_path(playlist.id)}/tracks',
      body: {
        'data': [
          {'id': partnerId, 'type': 'songs'},
        ],
      },
    );
  }

  /// The catalog id behind [song].
  ///
  /// A library song carries only its library id, and every write — rating,
  /// playlist membership — is keyed by the catalog's. The relationship is the
  /// only place the API states the correspondence, so it is read once per
  /// song and kept: the mapping never changes.
  final Map<String, String?> _partnerIds = {};

  Future<String?> _catalogIdOf(LibrarySong song) async {
    final known = song.catalogId;
    if (known != null) return known;
    if (_partnerIds.containsKey(song.id)) return _partnerIds[song.id];
    try {
      final body = await _get(
        '/v1/me/library/songs/${_path(song.id)}',
        query: {'include': 'catalog'},
      );
      final items = _resources(body);
      final relationships = items.isEmpty ? null : items.first['relationships'];
      final catalog = relationships is Map ? relationships['catalog'] : null;
      final data = catalog is Map ? catalog['data'] : null;
      final partner = data is List && data.isNotEmpty
          ? '${(data.first as Map)['id']}'
          : null;
      _partnerIds[song.id] = partner;
      return partner;
    } on LibraryException {
      _partnerIds[song.id] = null;
      return null;
    }
  }

  /// One call that changes the account.
  ///
  /// Every write in this class goes through here so the failure modes are
  /// spelled once: a refused write is a subscription or a scope problem, and
  /// a 4xx carries the store's own words for anything else.
  Future<void> _write(
    String verb,
    String path, {
    Map<String, dynamic>? body,
  }) async {
    try {
      switch (verb) {
        case 'put':
          await _dio.put<void>(path, data: body);
        case 'post':
          await _dio.post<void>(path, data: body);
        case 'delete':
          await _dio.delete<void>(path);
        default:
          throw ArgumentError.value(verb, 'verb');
      }
    } on DioException catch (error) {
      final status = error.response?.statusCode;
      if (status == 401 || status == 403) {
        throw LibraryException(
          'Apple Music refused the change (HTTP $status).',
          code: status,
          messageKey: 'libraryAppleMusicSubscription',
        );
      }
      throw describeAppleError(error);
    }
  }

  /// Artwork for a track the platform player only described by handle.
  ///
  /// A station's tracks exist in the catalog and nowhere else, so one catalog
  /// read is what turns `musicKit://artwork/transient/...` into a picture.
  /// The result is cached per track: a station can report the same entry many
  /// times, and each would otherwise cost a request.
  final Map<String, String?> _artCache = {};

  @override
  Future<String?> artworkTemplate(LibrarySong song) async {
    // Already a loadable template: nothing to resolve.
    final own = song.artId;
    if (own != null && own.startsWith('http')) return own;
    final catalogId = song.catalogId;
    if (catalogId == null) return null;
    if (_artCache.containsKey(catalogId)) return _artCache[catalogId];

    try {
      final storefront = await _storefront();
      final body = await _get('/v1/catalog/$storefront/songs/$catalogId');
      final items = _resources(body);
      final art = items.isEmpty ? null : _artTemplate(_attributes(items.first));
      _artCache[catalogId] = art;
      return art;
    } on LibraryException {
      // A cover that cannot be resolved is a missing cover, not a failure of
      // the track: the row draws its tonal fallback.
      _artCache[catalogId] = null;
      return null;
    }
  }

  /// The store the account reads from. Cached: it changes when the user
  /// travels, not between two tracks.
  String? _storefrontId;

  Future<String> _storefront() async {
    if (_storefrontId != null) return _storefrontId!;
    final body = await _get('/v1/me/storefront');
    final items = _resources(body);
    final id = items.isEmpty ? null : '${items.first['id']}';
    _storefrontId = id ?? 'us';
    return _storefrontId!;
  }

  /// One queue is all of one kind, and a station is not a song.
  @override
  String platformItemType(LibrarySong song) =>
      song.isRadio ? 'stations' : 'songs';

  /// `title` is a string on newer responses and a `{stringForDisplay}` map on
  /// the ones this account gets back.
  static String? _displayTitle(Object? title) {
    if (title is String) return title.isEmpty ? null : title;
    if (title is Map) {
      final display = title['stringForDisplay'];
      if (display is String && display.isNotEmpty) return display;
      final list = title['contentTitle'];
      if (list is String && list.isNotEmpty) return list;
    }
    return null;
  }

  /// There is no random endpoint, so a page from a random offset is shuffled.
  ///
  /// The offset is bounded by the library's own `meta.total`: picking blind
  /// inside a fixed range returns nothing at all for a library smaller than
  /// that range.
  @override
  Future<List<LibrarySong>> randomSongs({int size = 40}) async {
    final first = await _get('/v1/me/library/songs', query: {'limit': 1});
    final meta = first['meta'];
    final total = meta is Map ? (meta['total'] as num?)?.toInt() ?? 0 : 0;
    final offset = total > size ? Random().nextInt(total - size) : 0;
    final items = await _data(
      '/v1/me/library/songs',
      query: {'limit': size, 'offset': offset},
    );
    return [for (final item in items) _song(item)]..shuffle();
  }

  /// Apple does not expose library lyrics over the API; the resolver falls
  /// through to LRCLIB.
  @override
  Future<Lyrics> lyrics(LibrarySong song) async => Lyrics.empty;

  /// Never called: Apple Music items are played by [AppleMusicSource]'s
  /// platform player, not opened as a URL.
  @override
  Uri streamUri(LibrarySong song) => throw const LibraryException(
    'Apple Music tracks are played by the system player.',
    messageKey: 'libraryAppleMusicNoStream',
  );

  /// The art id is Apple's own template URL (`.../{w}x{h}bb.jpg`), so a
  /// cover is resized by substituting the size the widget actually paints.
  @override
  Uri? artworkUri(String? artId, {int size = 600}) {
    if (artId == null || artId.isEmpty) return null;
    // A station's track reports a `musicKit://artwork/transient/...` handle
    // that only the system player can load (see [artworkTemplate]); handing
    // it to a fetcher — the media session's cache, a share target — is the
    // unsupported-scheme error they answer with. Only a real image URL is a
    // cover this source can promise.
    if (!artId.startsWith('http')) return null;
    return Uri.tryParse(
      artId
          .replaceAll('{w}', '$size')
          .replaceAll('{h}', '$size')
          .replaceAll('{c}', 'bb')
          .replaceAll('{f}', 'jpg'),
    );
  }

  static String _path(String id) => Uri.encodeComponent(id);

  static Map<String, dynamic> _attributes(Map<String, dynamic> json) {
    final attributes = json['attributes'];
    return attributes is Map ? Map<String, dynamic>.from(attributes) : const {};
  }

  /// A cover template, or null when the item has none.
  static String? _artTemplate(Map<String, dynamic> attributes) {
    final artwork = attributes['artwork'];
    if (artwork is! Map) return null;
    final url = artwork['url'];
    return url is String && url.isNotEmpty ? url : null;
  }

  static Duration _duration(Map<String, dynamic> attributes) => Duration(
    milliseconds:
        (attributes['durationInMillis'] as num?)?.toInt() ??
        (attributes['durationInMillis'] as num?)?.round() ??
        0,
  );

  static int? _year(Map<String, dynamic> attributes) {
    final release = attributes['releaseDate'];
    if (release is! String || release.isEmpty) return null;
    return int.tryParse(release.substring(0, min(4, release.length)));
  }

  static String? _genre(Map<String, dynamic> attributes) {
    final genres = attributes['genreNames'];
    if (genres is! List) return null;
    // Apple's last genre is always "Music", which says nothing.
    final names = [
      for (final g in genres)
        if (g is String && g != 'Music') g,
    ];
    return names.isEmpty ? null : names.first;
  }

  LibrarySong _song(Map<String, dynamic> json, {String? albumId}) {
    final attributes = _attributes(json);
    return LibrarySong(
      sourceId: id,
      id: '${json['id']}',
      title: attributes['name'] as String? ?? 'Untitled',
      artist: attributes['artistName'] as String?,
      album: attributes['albumName'] as String?,
      albumId: albumId,
      artId: _artTemplate(attributes),
      duration: _duration(attributes),
      track: (attributes['trackNumber'] as num?)?.toInt(),
      discNumber: (attributes['discNumber'] as num?)?.toInt(),
      year: _year(attributes),
      genre: _genre(attributes),
    );
  }

  LibraryAlbum _album(Map<String, dynamic> json) {
    final attributes = _attributes(json);
    return LibraryAlbum(
      sourceId: id,
      id: '${json['id']}',
      name: attributes['name'] as String? ?? 'Untitled',
      artist: attributes['artistName'] as String?,
      artId: _artTemplate(attributes),
      songCount: (attributes['trackCount'] as num?)?.toInt(),
      duration: Duration.zero,
      year: _year(attributes),
      genre: _genre(attributes),
    );
  }
}

const _malformed = LibraryException(
  'Malformed Apple Music response.',
  messageKey: 'libraryMalformedResponse',
);

/// Transport failures the REST layer can diagnose itself, in the same
/// vocabulary the other adapters use.
LibraryException describeAppleError(DioException error) {
  switch (error.type) {
    case DioExceptionType.connectionTimeout:
    case DioExceptionType.receiveTimeout:
    case DioExceptionType.sendTimeout:
    case DioExceptionType.transformTimeout:
      return const LibraryException(
        'Apple Music took too long to respond.',
        messageKey: 'libraryTimeout',
      );
    case DioExceptionType.connectionError:
      return const LibraryException(
        'Could not reach Apple Music. Check your network.',
        messageKey: 'libraryUnreachableNetwork',
      );
    case DioExceptionType.badCertificate:
      return const LibraryException(
        "Apple Music's certificate is not valid.",
        messageKey: 'libraryBadCertificate',
      );
    case DioExceptionType.cancel:
      return const LibraryException(
        'Request cancelled.',
        messageKey: 'libraryRequestCancelled',
      );
    case DioExceptionType.badResponse:
      return const LibraryException(
        'Apple Music returned an error.',
        messageKey: 'libraryUnknownNetwork',
      );
    case DioExceptionType.unknown:
      return LibraryException(error.message ?? 'Unknown network error.');
  }
}
